[Fact]
public void Catalog_does_not_depend_on_any_module_internals()
{
    var result = Types.InAssembly(typeof(CatalogModuleFacade).Assembly)
        .ShouldNot()
        .HaveDependencyOnAny("Shop.Orders.Internal", "Shop.Shipping.Internal",
                             "Shop.Notifications.Internal", "Shop.Orders", "Shop.Shipping")
        .GetResult();

    result.IsSuccessful.Should().BeTrue(
        "الاعتماد المسموح على العقود فقط: " + string.Join(", ", result.FailingTypeNames ?? []));
}

